with feeders as (
    select
        md5(upper('REF_BANK_BRANCH_IFSC|' || (REF_BANK_BRANCH_IFSC_BK__IFSC_CODE))) as REF_BANK_BRANCH_IFSC_HK
        , BANK_NAME as BANK_NAME
        , CENTRE as NEFT_CLEARING_CENTRE_NAME
        , BRANCH_CONTACT_NO as BRANCH_CONTACT_NUMBER
        , 'BJAZ_NEFT_IFSC_MASTER' as RECORD_SOURCE
        , 'opus_health_v2' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_neft_ifsc_master') }}
    where (nullif(trim(IFSC_CODE),'')) is not null
),

resolved as (
    select
        REF_BANK_BRANCH_IFSC_HK,
        max(case when SOURCE_RUN = 'opus_health_v2' then BANK_NAME end) as BANK_NAME,
        max(case when SOURCE_RUN = 'opus_health_v2' then NEFT_CLEARING_CENTRE_NAME end) as NEFT_CLEARING_CENTRE_NAME,
        max(case when SOURCE_RUN = 'opus_health_v2' then BRANCH_CONTACT_NUMBER end) as BRANCH_CONTACT_NUMBER,
        min(RECORD_SOURCE) as RECORD_SOURCE,
        min(SOURCE_RUN) as SOURCE_RUN,
        min(LOAD_DATETIME) as LOAD_DATETIME
    from feeders
    group by REF_BANK_BRANCH_IFSC_HK
),

hashed as (
