        *,
        case when BANK_NAME is not null or NEFT_CLEARING_CENTRE_NAME is not null or BRANCH_CONTACT_NUMBER is not null
                     then md5(upper(coalesce(cast(BANK_NAME as varchar), '') || '|' || coalesce(cast(NEFT_CLEARING_CENTRE_NAME as varchar), '') || '|' || coalesce(cast(BRANCH_CONTACT_NUMBER as varchar), '')))
